def iniciales(nombre: str) -> str:
    # Split the string by any whitespace
    palabras = nombre.split()
    # Take the first character of each word, convert to uppercase, and join them
    return ''.join(word[0].upper() for word in palabras)

def planarizacion(datos):
    def flatten(element):
        result = []
        if isinstance(element, (list, tuple)):
            for item in element:
                result.extend(flatten(item))
        else:
            result.append(element)
        return result
    return flatten(datos)

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    if len(pesos) != len(valores):
        raise ValueError("pesos y valores deben tener la misma longitud")
    if any(w < 0 for w in pesos) or capacidad < 0:
        raise ValueError("pesos y capacidad no deben ser negativos")

    n = len(pesos)
    best_solution = (0, [])
    best_value = 0
    best_weight = 0
    best_count = 0
    best_indices = []

    # Generate all subsets
    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        selected_indices = []

        for i in range(n):
            if mask & (1 << i):
                total_weight += pesos[i]
                total_value += valores[i]
                selected_indices.append(i)

        # Check capacity constraint
        if total_weight > capacidad:
            continue

        # Evaluate according to criteria
        # 1. Higher value is better
        if total_value > best_value:
            update_criteria(total_value, total_weight, selected_indices, best_value, best_weight, best_count, best_indices)
        elif total_value == best_value:
            # 2. Lower weight is better
            if total_weight < best_weight:
                update_criteria(total_value, total_weight, selected_indices, best_value, best_weight, best_count, best_indices)
            elif total_weight == best_weight:
                # 3. Lower number of items is better
                if len(selected_indices) < best_count:
                    update_criteria(total_value, total_weight, selected_indices, best_value, best_weight, best_count, best_indices)
                elif len(selected_indices) == best_count:
                    # 4. Lexicographically smaller indices is better
                    if selected_indices < best_indices:
                        update_criteria(total_value, total_weight, selected_indices, best_value, best_weight, best_count, best_indices)

    return (best_value, best_indices)

def update_criteria(valor, peso, indices, valor_actual, peso_actual, count_actual, indices_actual):
    global best_solution
    best_solution = (valor, indices)
    best_value = valor
    best_weight = peso
    best_count = count_actual
    best_indices = indices

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if clave in self._datos:
            self._datos.move_to_end(clave)
            self._datos[clave] = valor
        else:
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
